describe('Search Tolerance for Minor Spelling Mistakes', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should find results with minor spelling mistakes', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('search');
    }).as('searchRequest');

    // Perform search with minor spelling mistake
    cy.get('[data-testid="search-input"]').type('appl');
    cy.get('[data-testid="search-button"]').click();

    // Wait for API response
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify first result is correct
    cy.get('[data-testid="result-item"]').first().should('contain', 'Apple');

    // Verify search result contains correct title
    cy.get('[data-testid="result-item"]').first().should('have.css', 'title', 'Apple Inc.');
  });

  it('should handle multiple minor spelling mistakes and still return results', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('search');
    }).as('searchRequest');

    // Perform search with multiple minor spelling mistakes
    cy.get('[data-testid="search-input"]').type('aplpe');
    cy.get('[data-testid="search-button"]').click();

    // Wait for API response
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify first result is correct
    cy.get('[data-testid="result-item"]').first().should('contain', 'Apple');

    // Verify search result contains correct title
    cy.get('[data-testid="result-item"]').first().should('have.css', 'title', 'Apple Inc.');

    // Verify other results are also displayed
    cy.get('[data-testid="result-item"]').last().should('contain', 'Apple');
  });
});
